// Script commands whose only operand is a name (generated by gen.pl).
#pragma once
#include "FunctionArgs/FunctionArgs.h"

struct StrArgList {
    virtual String ReadString(int flag);   // slot 0
};

class ShowPropFunction : public Function {
public:
    virtual int Execute(ScriptCall *args, int extra);
    virtual Function *Create(ArgList *list);
    virtual void Print();
    virtual const char *Name();
    String text;                                         // 0x04
};

